package accessanalyzer

import (
	"context"

	"github.com/amjadjibon/tinystack/internal/aws/awserror"
	api "github.com/amjadjibon/tinystack/internal/aws/generated/accessanalyzer"
	"github.com/amjadjibon/tinystack/internal/aws/request"
	"github.com/amjadjibon/tinystack/internal/common"
	"github.com/amjadjibon/tinystack/internal/storage"
)

// ListFindings retrieves a list of findings generated by the specified analyzer.
// TinyStack does not analyze policies, so analyzers produce no findings.
func (s *Service) ListFindings(
	ctx context.Context,
	in *api.ListFindingsRequest,
) (*api.ListFindingsResponse, error) {
	scope, err := request.RegionalScope(ctx)
	if err != nil {
		return nil, err
	}

	arn := common.Value(in.AnalyzerArn)
	analyzerName, err := parseAnalyzerArn(scope, arn)
	if err != nil {
		return nil, err
	}

	err = s.store.View(ctx, func(tx storage.ReadTx) error {
		_, found, readErr := storage.Read[analyzerRecord](tx, analyzerKey(scope, analyzerName))
		if readErr != nil {
			return readErr
		}

		if !found {
			return notFound("Analyzer", arn)
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	return &api.ListFindingsResponse{
		Findings: []api.FindingSummary{},
	}, nil
}

// GetFinding retrieves information about the specified finding.
// TinyStack does not analyze policies, so findings are never generated and this returns ResourceNotFoundException.
func (s *Service) GetFinding(
	ctx context.Context,
	in *api.GetFindingRequest,
) (*api.GetFindingResponse, error) {
	scope, err := request.RegionalScope(ctx)
	if err != nil {
		return nil, err
	}

	arn := common.Value(in.AnalyzerArn)
	analyzerName, err := parseAnalyzerArn(scope, arn)
	if err != nil {
		return nil, err
	}

	id := common.Value(in.Id)
	err = s.store.View(ctx, func(tx storage.ReadTx) error {
		_, found, readErr := storage.Read[analyzerRecord](tx, analyzerKey(scope, analyzerName))
		if readErr != nil {
			return readErr
		}

		if !found {
			return notFound("Analyzer", arn)
		}

		return notFound("Finding", id)
	})
	if err != nil {
		return nil, err
	}

	return nil, notFound("Finding", id)
}

// UpdateFindings updates the status for the specified findings.
// Because TinyStack does not generate findings, any provided finding ID is unknown and fails.
func (s *Service) UpdateFindings(
	ctx context.Context,
	in *api.UpdateFindingsRequest,
) (*api.UpdateFindingsOutput, error) {
	scope, err := request.RegionalScope(ctx)
	if err != nil {
		return nil, err
	}

	arn := common.Value(in.AnalyzerArn)
	analyzerName, err := parseAnalyzerArn(scope, arn)
	if err != nil {
		return nil, err
	}

	if len(in.Ids) == 0 {
		return nil, awserror.Validation("At least one finding ID must be specified.")
	}

	err = s.store.View(ctx, func(tx storage.ReadTx) error {
		_, found, readErr := storage.Read[analyzerRecord](tx, analyzerKey(scope, analyzerName))
		if readErr != nil {
			return readErr
		}

		if !found {
			return notFound("Analyzer", arn)
		}

		return notFound("Finding", in.Ids[0])
	})
	if err != nil {
		return nil, err
	}

	return nil, notFound("Finding", in.Ids[0])
}

